CREATE TABLE IF NOT EXISTS clinics ( id TEXT PRIMARY KEY, name TEXT NOT NULL, group_name TEXT, city TEXT, phone TEXT, address TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); INSERT OR IGNORE INTO clinics (id, name, group_name, city, phone, address) VALUES ( 'sri-rudra-mvp', 'Sri Rudra · MVP Double Road', 'Sri Rudra', 'Visakhapatnam', '9849848516', 'Flat No. 211 & 212, HIG-207/4, Second Floor, Beside Kotak Mahindra Bank, Bhavana Heights, MVP Double Road, Visakhapatnam-530017, Andhra Pradesh.' ); CREATE TABLE IF NOT EXISTS collections ( id INTEGER PRIMARY KEY AUTOINCREMENT, clinic_id TEXT NOT NULL REFERENCES clinics(id), collection_date TEXT NOT NULL, category TEXT NOT NULL, amount_paise INTEGER NOT NULL, method TEXT NOT NULL DEFAULT 'cash', phone TEXT, reference TEXT, notes TEXT, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_collections_date ON collections(collection_date, clinic_id); CREATE TABLE IF NOT EXISTS dashboard_notes ( note_date TEXT PRIMARY KEY, body TEXT NOT NULL DEFAULT '', updated_by INTEGER REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE TABLE IF NOT EXISTS crm_contacts ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, alt_phone TEXT, email TEXT, age TEXT, for_whom TEXT, area TEXT, language TEXT, source TEXT NOT NULL DEFAULT 'other', referred_by TEXT, interest TEXT, status TEXT NOT NULL DEFAULT 'lead', owner_id INTEGER REFERENCES users(id) ON DELETE SET NULL, patient_id INTEGER REFERENCES patients(id) ON DELETE SET NULL, notes TEXT, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_crm_contacts_phone ON crm_contacts(phone); CREATE INDEX IF NOT EXISTS idx_crm_contacts_status ON crm_contacts(status, updated_at); CREATE TABLE IF NOT EXISTS crm_deals ( id INTEGER PRIMARY KEY AUTOINCREMENT, contact_id INTEGER NOT NULL REFERENCES crm_contacts(id) ON DELETE CASCADE, title TEXT NOT NULL, deal_type TEXT NOT NULL DEFAULT 'other', stage TEXT NOT NULL DEFAULT 'new', value_paise INTEGER NOT NULL DEFAULT 0, expected_close TEXT, lost_reason TEXT, owner_id INTEGER REFERENCES users(id) ON DELETE SET NULL, stage_changed_at TEXT NOT NULL DEFAULT (datetime('now')), closed_at TEXT, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_crm_deals_stage ON crm_deals(stage, closed_at); CREATE INDEX IF NOT EXISTS idx_crm_deals_contact ON crm_deals(contact_id); CREATE TABLE IF NOT EXISTS crm_activities ( id INTEGER PRIMARY KEY AUTOINCREMENT, contact_id INTEGER NOT NULL REFERENCES crm_contacts(id) ON DELETE CASCADE, deal_id INTEGER REFERENCES crm_deals(id) ON DELETE SET NULL, kind TEXT NOT NULL DEFAULT 'call', body TEXT, due_date TEXT, done_at TEXT, outcome TEXT, assigned_to INTEGER REFERENCES users(id) ON DELETE SET NULL, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')) ); CREATE INDEX IF NOT EXISTS idx_crm_activities_open ON crm_activities(done_at, due_date); CREATE INDEX IF NOT EXISTS idx_crm_activities_contact ON crm_activities(contact_id, created_at);
